-- 파리 혼밥 맛집과 모든 요청 카테고리를 등록·갱신한다.
-- PostgreSQL / Supabase SQL Editor용. 변경된 서버의 Flyway로 V28 적용 후 이 파일 전체를 실행한다.
-- V28 마이그레이션 파일은 수동 실행하지 않는다. 앱 기동 시 Flyway가 적용 이력을 관리한다.
-- 원본: 혼밥 맛집_파리_정지영.xlsx / 기획 요청!B5:E105.
-- 장소 정보: 2026-10-15 Google Places API 조회. 원본 100건은 공유 링크의 CID와 좌표까지 일치 확인.
-- 포르투를 가리키던 26행은 사용자 요청에 따라 파리 Opéra점으로 교체했다.
-- 100행 Boulangerie Colette Bakery는 원본 링크대로 파리 인근 Montrouge 지점을 유지했다.
-- 디저트 가게는 DESSERT로 저장하고, 원본 첫 번째 분류를 대표 category로 유지한다.
-- 동일 google_place_id는 기존 id를 유지하며 갱신한다. 즐겨찾기·동행 데이터는 변경하지 않는다.
-- 대상 장소의 place_category만 원본 분류로 교체한다. 다른 장소는 변경하지 않는다.
-- 장소 101건 / 카테고리 119건.

begin;

create temporary table paris_solo_dining_seed (
    google_place_id varchar(255) primary key,
    name varchar(255) not null,
    address varchar(255),
    latitude numeric(11, 8) not null,
    longitude numeric(11, 8) not null,
    category varchar(255) not null,
    secondary_category varchar(255),
    phone_number varchar(255),
    rating numeric(38, 2),
    review_count integer,
    photo_reference text,
    business_status varchar(255) not null
) on commit drop;

insert into paris_solo_dining_seed (
    google_place_id, name, address, latitude, longitude, category, secondary_category,
    phone_number, rating, review_count, photo_reference, business_status
) values
