insert into place_cache (
    google_place_id, name, address, latitude, longitude, category,
    phone_number, rating, review_count, photo_reference, business_status
)
select google_place_id, name, address, latitude, longitude, category,
       phone_number, rating, review_count, photo_reference, business_status
from paris_solo_dining_seed
on conflict (google_place_id) do update set
    name = excluded.name,
    address = excluded.address,
    latitude = excluded.latitude,
    longitude = excluded.longitude,
    category = excluded.category,
    phone_number = excluded.phone_number,
    rating = excluded.rating,
    review_count = excluded.review_count,
    photo_reference = excluded.photo_reference,
    business_status = excluded.business_status;

delete from place_category classification
using place_cache place, paris_solo_dining_seed seed
where classification.place_id = place.id and place.google_place_id = seed.google_place_id;

insert into place_category (place_id, category, category_order)
select place.id, seed.category, 0
from paris_solo_dining_seed seed
join place_cache place on place.google_place_id = seed.google_place_id
union all
select place.id, seed.secondary_category, 1
from paris_solo_dining_seed seed
join place_cache place on place.google_place_id = seed.google_place_id
where seed.secondary_category is not null;

-- 등록 결과: 복수 분류를 포함하므로 카테고리별 매장 수 합계는 전체 매장 수보다 클 수 있다.
select classification.category, count(*) as place_count
from place_category classification
join place_cache place on place.id = classification.place_id
join paris_solo_dining_seed seed on seed.google_place_id = place.google_place_id
group by classification.category
order by classification.category;

select count(*) as registered_place_count
from place_cache place
join paris_solo_dining_seed seed on seed.google_place_id = place.google_place_id;

commit;
